import {albumImportPlan} from './album-import-model.mjs?v=1';
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
export function initAlbumImport({catalog,getSnapshot,onSave,host}){
 const button=el('button','Import screenshots','btn secondary');button.type='button';button.id='album-screenshot-open';host.append(button);
 const dialog=el('dialog',undefined,'screenshot-import');dialog.id='album-screenshot-dialog';dialog.setAttribute('aria-labelledby','album-import-title');
 const header=el('div',undefined,'screenshot-import-head modal-head'),title=el('h2','Import album screenshots'),close=el('button','×');title.id='album-import-title';close.type='button';close.setAttribute('aria-label','Close album import');header.append(title,close);
 const body=el('div',undefined,'screenshot-import-body'),intro=el('p','Choose up to 15 screenshots, one complete album set per image. Readable card counts replace your saved quantities.','screenshot-import-intro'),privacy=el('p','Images are read on this device. Only card counts are saved to your account. Sets you do not upload stay unchanged.','screenshot-import-note'),foil=el('p','Foil settings are not read from screenshots. Your saved foil settings are kept, except when the new quantity no longer supports them. Use current screenshots after trading cards.','screenshot-import-note'),label=el('label','Choose up to 15 screenshots','screenshot-import-upload'),input=el('input');input.type='file';input.multiple=true;input.accept='image/*';label.append(input);
 const status=el('p','','screenshot-import-progress'),error=el('p','','screenshot-import-error'),list=el('div',undefined,'screenshot-import-list');status.setAttribute('role','status');status.setAttribute('aria-live','polite');error.setAttribute('role','alert');body.append(intro,privacy,label,foil,status,error,list);
 const actions=el('div',undefined,'screenshot-import-actions'),undoButton=el('button','Undo last import','btn secondary');undoButton.type='button';undoButton.hidden=true;actions.append(undoButton);dialog.append(header,body,actions);document.body.append(dialog);
 let worker=null,waiter=null,serial=0,busy=false,saving=false,undo=null;
 function stop(){worker?.terminate();worker=null;if(waiter){waiter.reject(Error('Import cancelled.'));waiter=null}}
 function reset(forget=true){serial++;saving=false;close.disabled=false;stop();busy=false;input.value='';input.disabled=false;error.textContent='';status.textContent='';list.replaceChildren();if(forget)undo=null;undoButton.hidden=!undo;undoButton.disabled=false;if(dialog.open)dialog.close()}
 function request(data,transfer=[]){return new Promise((resolve,reject)=>{waiter={resolve,reject};worker.postMessage(data,transfer)})}
 async function ready(){worker=new Worker(new URL('./album-import-worker.mjs?v=1',import.meta.url),{type:'module'});const active=worker;worker.onmessage=({data})=>{if(data.type==='progress')return;const p=waiter;waiter=null;if(p)data.type==='error'?p.reject(Error(data.message)):p.resolve(data)};worker.onerror=()=>{waiter?.reject(Error('Image reading is unavailable in this browser.'));waiter=null};const [references,atlas,setAtlas]=await Promise.all([fetch(new URL('./album-import/references.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Card references unavailable.');return r.json()}),fetch(new URL('./album-import/cards.webp',import.meta.url)).then(r=>{if(!r.ok)throw Error('Card artwork unavailable.');return r.blob()}),fetch(new URL('./album-import/sets.webp',import.meta.url)).then(r=>{if(!r.ok)throw Error('Set artwork unavailable.');return r.blob()})]);if(worker!==active)throw Error('Import cancelled.');await request({type:'load',references,atlas,setAtlas})}
 function show(plan){list.replaceChildren();for(const r of plan.results){const row=el('article',undefined,'screenshot-import-result'),text=el('div');if(r.record.crop)row.append(r.record.crop);text.append(el('h3',`#${r.number} · ${r.name}`),el('p',r.status==='skipped'?'Skipped · '+r.reason:r.status==='imported'?`${r.quantity} total copies · Imported`:r.status==='repeated'?'Repeated screenshot · Count used once':`${r.quantity} total copies · Already matches`));row.append(text);list.append(row)}}
 button.onclick=()=>{reset(false);privacy.textContent=getSnapshot().preview?'Local preview: changes stay on this page and reset when you reload. Your account is not changed.':'Images are read on this device. Only card counts are saved to your account. Sets you do not upload stay unchanged.';dialog.showModal();status.textContent='Missing card backs count as zero. A card without a copy badge counts as one.'};close.onclick=()=>{if(!saving)reset(false)};dialog.addEventListener('cancel',e=>{e.preventDefault();if(!saving)reset(false)});
 input.onchange=async()=>{const files=[...input.files];if(!files.length)return;const token=++serial,snapshot=getSnapshot();stop();list.replaceChildren();error.textContent='';undo=null;undoButton.hidden=true;busy=true;input.disabled=true;let plan;try{if(files.length>15)throw Error('Choose no more than 15 screenshots.');if(!snapshot.canSave)throw Error('Wait for your album to finish saving, then try again.');status.textContent='Loading card references…';await ready();if(token!==serial)return;const records=[],failures=[];for(let i=0;i<files.length;i++){if(token!==serial)return;status.textContent=`Reading screenshot ${i+1} of ${files.length}…`;let bitmap;try{if(files[i].size>12*1024*1024)throw Error('Image exceeds 12 MB.');bitmap=await createImageBitmap(files[i]);if(bitmap.width*bitmap.height>24000000)throw Error('Image is too large.');const scale=Math.min(1,900/bitmap.width,3000/bitmap.height);if(scale<1){const small=await createImageBitmap(bitmap,{resizeWidth:Math.round(bitmap.width*scale),resizeHeight:Math.round(bitmap.height*scale)});bitmap.close();bitmap=small}const copy=await createImageBitmap(bitmap),result=await request({type:'scan',image:copy},[copy]);if(token!==serial)return;if(!result.cards.length){failures.push(`Screenshot ${i+1}: ${result.reason||'No complete album set found.'}`);continue}for(const record of result.cards){const crop=el('canvas');crop.width=82;crop.height=118;crop.getContext('2d').drawImage(bitmap,record.box.x,record.box.y,record.box.w,record.box.h,0,0,82,118);crop.setAttribute('role','img');crop.setAttribute('aria-label','Card '+record.number+' screenshot crop');records.push({...record,fileIndex:i,crop})}}catch(e){failures.push(`Screenshot ${i+1}: ${e.message}`)}finally{bitmap?.close()}}
 plan=albumImportPlan(catalog,new Map(snapshot.inventory),records);if(plan.changes.length){saving=true;close.disabled=true;status.textContent=`Saving ${plan.changes.length} card counts…`;await onSave(plan.changes,snapshot);if(token!==serial)return;undo={changes:plan.changes.map(c=>({number:c.number,before:c.after,after:c.before})),snapshot:getSnapshot()};undoButton.hidden=false}show(plan);status.textContent=`${plan.changes.length} updated · ${plan.unchanged} unchanged · ${plan.repeated} repeated · ${plan.skipped} unread.`;error.textContent=failures.join('\n');if(!records.length&&!failures.length)error.textContent='No complete album sets found.';
 }catch(e){if(token===serial){status.textContent=saving?'The import was not confirmed. Refresh your album before retrying.':'No new card counts were saved.';error.textContent=e.message;if(plan){for(const r of plan.results)if(r.status==='imported'){r.status='skipped';r.reason='Not saved.'}show(plan)}}}finally{if(token===serial){busy=saving=false;input.disabled=false;close.disabled=false;stop()}}};
 undoButton.onclick=async()=>{if(!undo||busy)return;const previous=undo;try{busy=saving=true;input.disabled=close.disabled=undoButton.disabled=true;await onSave(previous.changes,previous.snapshot);undo=null;undoButton.hidden=true;list.replaceChildren();status.textContent='Last screenshot import undone.';error.textContent=''}catch(e){error.textContent=e.message}finally{busy=saving=false;input.disabled=close.disabled=undoButton.disabled=false}};
 return {reset:()=>reset(true)};
}
